import * as THREE from 'three';
import {FullScreenQuad} from 'three/addons/postprocessing/Pass.js';

// inferred: one periodic 64×64 field of overlapping, chisel-ended marks.
// R holds a constant load, G/B the displacement to its centre, A its edge distance.
// All randomness is generated by this fixed GLSL hash; no external texture.
export const MARK_BAKE_GLSL=/* glsl */`
float markHash(vec2 p){return fract(sin(dot(mod(p,64.),vec2(127.1,311.7)))*43758.5453);}
vec4 brushField(vec2 p){
  vec2 cell=floor(p),chosen=vec2(0.),center=vec2(0.);float best=1.e6,second=1.e6;
  for(int y=-1;y<=1;y++)for(int x=-1;x<=1;x++){
    vec2 id=cell+vec2(float(x),float(y));
    vec2 c=id+.5+(vec2(markHash(id+13.),markHash(id+29.))-.5)*.78;
    float angle=(markHash(id+41.)-.5)*.65;
    vec2 r=mat2(cos(angle),sin(angle),-sin(angle),cos(angle))*(p-c);
    // Unequal clipped ends and a little edge tooth, never an interior wash.
    float edge=max(abs(r.x)*(.85+.30*markHash(id+7.)),abs(r.y)*(1.05+.35*markHash(id+19.)));
    edge+=.035*sin(p.x*31.+id.y)*sin(p.y*27.+id.x);
    if(edge<best){second=best;best=edge;chosen=id;center=c;}else second=min(second,edge);
  }
  float h=markHash(chosen+3.);
  return vec4(h,(center-p)*.25+.5,clamp((second-best)*2.,0.,1.));
}`;

export function bakeMarks(engine,time){
  const start=performance.now(),target=new THREE.WebGLRenderTarget(1024,1024,{
    minFilter:THREE.LinearMipmapLinearFilter,magFilter:THREE.LinearFilter,
    wrapS:THREE.RepeatWrapping,wrapT:THREE.RepeatWrapping,generateMipmaps:true,
    type:THREE.HalfFloatType,depthBuffer:false,stencilBuffer:false,colorSpace:THREE.NoColorSpace});
  const material=new THREE.ShaderMaterial({depthTest:false,depthWrite:false,
    vertexShader:'varying vec2 vUv;void main(){vUv=uv;gl_Position=vec4(position.xy,0.,1.);}',
    fragmentShader:`varying vec2 vUv;${MARK_BAKE_GLSL}void main(){gl_FragColor=brushField(vUv*64.);}`});
  const quad=new FullScreenQuad(material),r=engine.renderer,saved=r.getRenderTarget();
  try{r.setRenderTarget(target);quad.render(r);r.readRenderTargetPixels(target,0,0,1,1,new Uint16Array(4));}
  finally{r.setRenderTarget(saved);material.dispose();quad.dispose();}
  const uniforms={paintMarks:{value:target.texture},paintPixelScale:{value:engine.height/1080},paintMarkStrength:{value:1}};
  engine.onUpdate(()=>{uniforms.paintPixelScale.value=engine.height/1080;});
  time.marks={target,uniforms,bakeMs:performance.now()-start,size:1024,cells:64};
  engine.registry.paint.marks=time.marks;
  console.log('[paint marks]',JSON.stringify({ms:time.marks.bakeMs,size:1024}));
}

export const MARK_SAMPLE_GLSL=/* glsl */`
uniform sampler2D paintMarks;
uniform float paintPixelScale,paintMarkStrength;
struct PaintMark{vec3 p;vec3 n;vec2 uv;float load;float pick;};
PaintMark getMark(vec2 q,float scale,vec3 n,vec3 tangent,vec3 bitangent,vec3 normalU,vec3 normalV,vec2 uvU,vec2 uvV){
  vec4 tex=texture2D(paintMarks,q*scale/64.);
  vec2 offset=(tex.gb-.5)*4./scale;
  vec3 delta=tangent*offset.x+bitangent*offset.y;
  float reach=abs(vKind-9.)<.5||abs(vKind-77.)<.5||abs(vKind-78.)<.5?.12:.60;
  delta*=min(1.,reach/max(length(delta),.00001));
  vec3 bend=normalU*offset.x+normalV*offset.y;bend*=min(1.,.30/max(length(bend),.00001));
  PaintMark m;m.p=vP+delta;
  m.n=normalize(n+bend);
  m.uv=vUv+uvU*offset.x+uvV*offset.y;m.pick=tex.r;m.load=tex.r<.18?tex.r/.18*.30:tex.r>.82?.70+(tex.r-.82)/.18*.30:.5+(tex.r-.5)*.25;return m;
}
float markLight(float sun,float pick){
  // inferred: twelve small, irregular decisions, evaluated at a mark centre.
  // The mark load offsets the thresholds, avoiding image-wide toon contours.
  float light=clamp(sun*1.45+(pick-.5)*.09,0.,1.);
  return clamp(floor(light*12.+.5)/12.,0.,1.);
}
`;
